class Command(BaseCommand):
    help = 'Seed all Vital Hub products into the database'

    def handle(self, *args, **options):
        from django.utils import timezone
        from datetime import timedelta

        base = timezone.now()
        created = updated = 0
        for i, data in enumerate(PRODUCTS):
            # Assign descending timestamps so index 0 appears first in -created_at sort
            ts = base - timedelta(seconds=i * 10)
            obj, is_new = Product.objects.update_or_create(id=data['id'], defaults=data)
            Product.objects.filter(id=data['id']).update(created_at=ts)
            if is_new:
                created += 1
            else:
                updated += 1
        self.stdout.write(self.style.SUCCESS(
            f'Done — {created} created, {updated} updated ({len(PRODUCTS)} total products)'
        ))
